import { useMemo } from "react";

export function DerivedState({
  a = {{a}},
  b = {{b}},
  operation = "{{operation}}",
  accent = "{{accent}}",
}) {
  const total = useMemo(() => (operation === "sum" ? a + b : operation === "difference" ? a - b : a * b), [a, b, operation]);
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 8px", fontSize: 12 }}>price = {a} &nbsp; quantity = {b}</p>
      <p style={{ margin: "0 0 8px", fontFamily: "ui-monospace, monospace", fontSize: 11, color: "#24143099" }}>total = f(price, {operation}, quantity)</p>
      <p style={{ margin: "0 0 10px", fontSize: 22, fontWeight: 800, color: accent }}>total = {total}</p>
      <p style={{ margin: 0, fontSize: 10, color: "#24143099" }}>total is never stored &mdash; it's recomputed from price and quantity every render.</p>
    </div>
  );
}
